/**
 * The contract `popover.tsx` (native) and `popover.web.tsx` (radix) both
 * implement. Its own module for the usual reason: Metro resolves `./popover`
 * to `popover.web.tsx` on web, so the web file cannot import shared types from
 * `./popover` without importing itself.
 *
 * Narrower than radix's props on purpose: an `asChild` trigger and one content
 * pane. That is the shape both platforms can honour — everything radix offers
 * beyond it (collision handling, side flipping, a separate anchor) has no native
 * counterpart. The web half accepts it all the same, on top of this contract,
 * because it is a drop-in for shadcn's `popover`: `popover.web.tsx` widens each
 * part to the radix part it renders. Those extras are web only, and on native a
 * `PopoverAnchor` simply renders its children.
 */
import type { ReactNode } from "react";

export type PopoverProps = {
  /**
   * Both optional, together: pass neither and the popover keeps its own open
   * state. `form-field` opens a hint popover from a trigger and never reads the
   * state back, and requiring the pair there meant a `useState` at every call
   * site that existed only to be handed straight back.
   */
  open?: boolean | undefined;
  onOpenChange?: ((open: boolean) => void) | undefined;
  defaultOpen?: boolean | undefined;
  children: ReactNode;
};

export type PopoverTriggerProps = {
  /**
   * Hand the press handler to the single child element rather than wrapping it.
   * Always pass it: a `Pressable` wrapping a `Button` never fires on native,
   * because the inner pressable claims the touch responder.
   */
  asChild?: boolean | undefined;
  children: ReactNode;
};

export type PopoverContentProps = {
  className?: string | undefined;
  /** Web only — the native sheet is centred and has nothing to align to. */
  align?: "start" | "center" | "end" | undefined;
  children?: ReactNode;
};

/**
 * Closes the popover it is inside. `asChild` hands the press to a `Button` rather than wrapping
 * it — the same shape as `DialogClose`, so a pane's Done button does not need the caller to own
 * `open` just to set it back to `false`.
 */
export type PopoverCloseProps = {
  asChild?: boolean | undefined;
  className?: string | undefined;
  children?: ReactNode;
};

/** Web only in effect: the native sheet is centred, so it renders its children and anchors nothing. */
export type PopoverAnchorProps = {
  asChild?: boolean | undefined;
  children?: ReactNode;
};

/** `PopoverHeader`, `PopoverTitle` and `PopoverDescription` — shadcn's heading block for a pane. */
export type PopoverSectionProps = {
  className?: string | undefined;
  children?: ReactNode;
};

/**
 * The native popover: a transparent `Modal` with a dimmed backdrop and a
 * centred card.
 *
 * It is deliberately *not* anchored to its trigger. Anchoring means measuring
 * the trigger and flipping the card against the viewport, which is a chunk of
 * layout code to reproduce a hover-era affordance — on a phone a centred sheet
 * is the native idiom anyway. `align` is accepted and ignored, and the same
 * backdrop-as-sibling rule as `dialog.tsx` applies (a `Pressable` has no
 * `stopPropagation`, so the card must not be nested inside it).
 */

import {
  cloneElement,
  createContext,
  isValidElement,
  type ReactElement,
  useContext,
  useState,
} from "react";
import { Modal, Pressable, Text, View } from "react-native";
import type {
  PopoverAnchorProps,
  PopoverCloseProps,
  PopoverContentProps,
  PopoverProps,
  PopoverSectionProps,
  PopoverTriggerProps,
} from "@/components/ui/popover-base";
import { cn } from "@/lib/utils";

type PopoverState = { open: boolean; setOpen: (open: boolean) => void };

const PopoverContext = createContext<PopoverState>({
  open: false,
  setOpen: () => {},
});

function Popover({ open, onOpenChange, defaultOpen = false, children }: PopoverProps) {
  // Uncontrolled state kept unconditionally — hooks cannot be conditional — and
  // read only when the caller passed no `open`.
  const [uncontrolled, setUncontrolled] = useState(defaultOpen);
  const isOpen = open ?? uncontrolled;
  const setOpen = (next: boolean) => {
    if (open === undefined) setUncontrolled(next);
    onOpenChange?.(next);
  };
  return (
    <PopoverContext.Provider value={{ open: isOpen, setOpen }}>{children}</PopoverContext.Provider>
  );
}

function PopoverTrigger({ asChild, children }: PopoverTriggerProps) {
  const { setOpen } = useContext(PopoverContext);
  if (asChild && isValidElement(children)) {
    return cloneElement(children as ReactElement<{ onPress?: () => void }>, {
      onPress: () => setOpen(true),
    });
  }
  return (
    // The `role` is hand-written because a `<button>` has no native counterpart.
    <Pressable role="button" onPress={() => setOpen(true)}>
      {children}
    </Pressable>
  );
}

function PopoverContent({ className, children }: PopoverContentProps) {
  const { open, setOpen } = useContext(PopoverContext);
  return (
    <Modal visible={open} transparent animationType="fade" onRequestClose={() => setOpen(false)}>
      <View className="flex-1 items-center justify-center bg-black/60 p-6">
        <Pressable
          className="absolute inset-0"
          onPress={() => setOpen(false)}
          role="button"
          aria-label="Close"
        />
        <View className={cn("w-72 rounded-md border border-border bg-popover p-4", className)}>
          {children}
        </View>
      </View>
    </Modal>
  );
}

function PopoverClose({ asChild, className, children }: PopoverCloseProps) {
  const { setOpen } = useContext(PopoverContext);
  if (asChild && isValidElement(children)) {
    return cloneElement(children as ReactElement<{ onPress?: () => void }>, {
      onPress: () => setOpen(false),
    });
  }
  return (
    // The `role` is hand-written because a `<button>` has no native counterpart.
    <Pressable role="button" onPress={() => setOpen(false)} className={cn(className)}>
      {children}
    </Pressable>
  );
}

/** The native sheet is centred and anchors to nothing, so an anchor is just its children. */
function PopoverAnchor({ children }: PopoverAnchorProps) {
  return <>{children}</>;
}

function PopoverHeader({ className, children }: PopoverSectionProps) {
  return <View className={cn("gap-1", className)}>{children}</View>;
}

function PopoverTitle({ className, children }: PopoverSectionProps) {
  return (
    <Text className={cn("text-sm font-medium text-popover-foreground", className)}>{children}</Text>
  );
}

function PopoverDescription({ className, children }: PopoverSectionProps) {
  return <Text className={cn("text-sm text-muted-foreground", className)}>{children}</Text>;
}

export {
  Popover,
  PopoverAnchor,
  PopoverClose,
  PopoverContent,
  PopoverDescription,
  PopoverHeader,
  PopoverTitle,
  PopoverTrigger,
};

/**
 * The web popover: radix, anchored to its trigger. `popover.tsx` is the native
 * counterpart and `popover-base.ts` holds the contract they share.
 *
 * Every part also takes the props of the radix part (or element) it renders, as
 * shadcn's `popover` does — `side`, `sideOffset`, `onOpenAutoFocus`, `modal`, a
 * `PopoverAnchor` — so a DOM call site written against shadcn compiles and
 * behaves unchanged. Those extras are web only.
 */

import { Popover as PopoverPrimitive } from "radix-ui";
import type * as React from "react";
import type {
  PopoverAnchorProps,
  PopoverCloseProps,
  PopoverContentProps,
  PopoverProps,
  PopoverSectionProps,
  PopoverTriggerProps,
} from "@/components/ui/popover-base";
import { cn } from "@/lib/utils";

/** The shared contract, widened to what the radix part (or element) underneath accepts. */
type Wide<Base, Radix> = Base & Omit<Radix, keyof Base>;

function Popover({
  open,
  onOpenChange,
  defaultOpen,
  ...props
}: Wide<PopoverProps, React.ComponentProps<typeof PopoverPrimitive.Root>>) {
  // Spread rather than passed: radix switches to uncontrolled on `open === undefined`,
  // but only if the prop is absent, and `exactOptionalPropertyTypes` is what makes the
  // difference expressible.
  return (
    <PopoverPrimitive.Root
      data-slot="popover"
      {...props}
      {...(open === undefined ? {} : { open })}
      {...(onOpenChange === undefined ? {} : { onOpenChange })}
      {...(defaultOpen === undefined ? {} : { defaultOpen })}
    />
  );
}

function PopoverTrigger({
  asChild,
  ...props
}: Wide<PopoverTriggerProps, React.ComponentProps<typeof PopoverPrimitive.Trigger>>) {
  return (
    <PopoverPrimitive.Trigger data-slot="popover-trigger" asChild={asChild ?? false} {...props} />
  );
}

function PopoverContent({
  className,
  align = "center",
  sideOffset = 4,
  ...props
}: Wide<PopoverContentProps, React.ComponentProps<typeof PopoverPrimitive.Content>>) {
  return (
    <PopoverPrimitive.Portal>
      <PopoverPrimitive.Content
        data-slot="popover-content"
        align={align}
        sideOffset={sideOffset}
        className={cn(
          "z-50 w-72 rounded-md border bg-popover p-4 text-popover-foreground shadow-md outline-none data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95",
          className,
        )}
        {...props}
      />
    </PopoverPrimitive.Portal>
  );
}

function PopoverAnchor({
  asChild,
  ...props
}: Wide<PopoverAnchorProps, React.ComponentProps<typeof PopoverPrimitive.Anchor>>) {
  return (
    <PopoverPrimitive.Anchor data-slot="popover-anchor" asChild={asChild ?? false} {...props} />
  );
}

function PopoverClose({
  asChild,
  className,
  ...props
}: Wide<PopoverCloseProps, React.ComponentProps<typeof PopoverPrimitive.Close>>) {
  return (
    <PopoverPrimitive.Close
      data-slot="popover-close"
      asChild={asChild ?? false}
      {...(className === undefined ? {} : { className })}
      {...props}
    />
  );
}

function PopoverHeader({
  className,
  ...props
}: Wide<PopoverSectionProps, React.ComponentProps<"div">>) {
  return (
    <div
      data-slot="popover-header"
      className={cn("flex flex-col gap-1 text-sm", className)}
      {...props}
    />
  );
}

function PopoverTitle({
  className,
  ...props
}: Wide<PopoverSectionProps, React.ComponentProps<"div">>) {
  return <div data-slot="popover-title" className={cn("font-medium", className)} {...props} />;
}

function PopoverDescription({
  className,
  ...props
}: Wide<PopoverSectionProps, React.ComponentProps<"p">>) {
  return (
    <p
      data-slot="popover-description"
      className={cn("text-muted-foreground", className)}
      {...props}
    />
  );
}

export {
  Popover,
  PopoverAnchor,
  PopoverClose,
  PopoverContent,
  PopoverDescription,
  PopoverHeader,
  PopoverTitle,
  PopoverTrigger,
};
